  'help.send': 'Pošalji tiket',
  'help.ticketSent': 'Ulaznica poslana!',
  'help.ticketSentDesc': 'Primili smo tvoj zahtjev. Naš tim će odgovoriti putem emaila u roku od 24 sata.',
  'help.close': 'Zatvori',
  'help.ticketError': 'Neuspjeh pri slanju ulaznice. Pokušaj ponovo.',
  'help.type.cant_login': 'Ne mogu se prijaviti',
  'help.type.email_issue': 'Problem s emailom',
  'help.type.security': 'Sigurnost',
  'help.type.other': 'Drugo',
  'help.faq.cantLogin.q': 'Ne mogu pristupiti svom računu',
  'help.faq.cantLogin.a': 'Provjeri koristiš li ispravnu email adresu i lozinku. Ako si zaboravio lozinku, klikni na "Zaboravio si lozinku?" na ekranu za prijavu. Ako problem i dalje traje, stvori ulaznicu za podršku.',
  'help.faq.notReceiving.q': 'Ne primam emailove',
  'help.faq.notReceiving.a': 'Prvo provjeri mapu za neželjenu poštu. Uvjeri se da ti pohrana nije puna. Ako problem nastavi, potvrdi da pošiljatelj ima ispravnu adresu i stvori ulaznicu.',
  'help.faq.cantSend.q': 'Ne mogu slati emailove',
  'help.faq.cantSend.a': 'Provjeri svoju internetsku vezu i je li adresa primatelja ispravna. Provjeri jesu li privitci manji od 25MB. Pokušaj ponovo za nekoliko minuta.',
  'help.faq.forgotPassword.q': 'Zaboravio sam svoju lozinku',
  'help.faq.forgotPassword.a': 'Na ekranu za prijavu, klikni na "Zaboravio si lozinku?" i slijedi upute za resetiranje lozinke putem emaila za oporavak.',
  'help.faq.accountSecurity.q': 'Mislim da je moj račun kompromitiran',
  'help.faq.accountSecurity.a': 'Odmah promijeni svoju lozinku. Provjeri mapu Poslano za poruke koje nisi poslao. Aktiviraj dvostruku autentifikaciju u Postavkama > Sigurnost. Ako je potrebno, stvori hitnu ulaznicu.',
  'help.faq.appAccess.q': 'Kako pristupam aplikaciji na mobitelu?',
  'help.faq.appAccess.a': 'Možeš pristupiti Chatyy-u putem preglednika na chatyy.com.br, ili preuzeti našu aplikaciju iz trgovine aplikacija na svom uređaju.',
  'privacy.title': 'Politika privatnosti',
  'privacy.subtitle': 'Kako štitimo i obrađujemo tvoje podatke',
  'privacy.lastUpdated': 'Zadnja ažuriranja: Ožujak 2026',
  'privacy.dataCollection.title': 'Prikupljanje podataka',
  'privacy.dataCollection.body': 'Prikupljamo samo informacije potrebne za uslugu emaila: tvoje ime, email adresu i sadržaj poslanih i primljenih poruka. Ne prodajemo niti dijelimo tvoje osobne podatke s trećim stranama u marketinške svrhe.',
  'privacy.dataUsage.title': 'Kako koristimo tvoje podatke',
  'privacy.dataUsage.body': 'Tvoji podaci se koriste isključivo za rad i poboljšanje usluge emaila, uključujući isporuku poruka, filtriranje neželjene pošte, AI značajke (uz tvoju suglasnost) i sigurnost računa.',
  'privacy.dataSecurity.title': 'Sigurnost podataka',
  'privacy.dataSecurity.body': 'Koristimo industrijsku enkripciju (TLS/SSL) za sve podatke u prijenosu i mirovanju. Sesije su zaštićene kriptografskim tokenima i CSRF zaštitom. Redovito provjeravamo naše sigurnosne prakse.',
  'privacy.cookies.title': 'Kolačići i lokalno pohranjivanje',
  'privacy.cookies.body': 'Koristimo osnovne kolačiće i lokalno pohranjivanje za održavanje tvoje sesije, pamćenje tvojih postavki (tema, jezik) i pružanje fluidnog iskustva. Ne koristimo kolačiće za praćenje trećih strana.',
  'privacy.thirdParties.title': 'Usluge trećih strana',
  'privacy.thirdParties.body': 'Možemo koristiti usluge trećih strana za specifične funkcionalnosti kao što su AI (Anthropic Claude) i push obavijesti. Ove usluge slijede vlastite politike privatnosti i obrađuju samo minimalne potrebne podatke.',
  'privacy.rights.title': 'Tvoja prava',
  'privacy.rights.body': 'Imaš pravo pristupiti, ispraviti, izvesti ili izbrisati svoje osobne podatke u bilo kojem trenutku. Možeš upravljati svojim podacima u Postavkama ili kontaktirati našu podršku.',
  'privacy.contact.title': 'Kontaktiraj nas',
  'privacy.contact.body': 'Za pitanja o privatnosti ili zahtjeve za podatke, kontaktiraj nas na privacy@chatyy.com.br. Odgovorit ćemo u roku od 30 dana.',
  'terms.title': 'Uvjeti usluge',
  'terms.subtitle': 'Smjernice za korištenje Chatyy-a',
  'terms.lastUpdated': 'Zadnja ažuriranja: Ožujak 2026',
  'terms.acceptance.title': 'Prihvaćanje uvjeta',
  'terms.acceptance.body': 'Pristupanjem ili korištenjem Chatyy-a, slažeš se s ovim Uvjetima usluge. Ako se ne slažeš s bilo kojim dijelom ovih uvjeta, nemoj koristiti uslugu.',
  'terms.services.title': 'Opis usluga',
  'terms.services.body': 'Chatyy pruža usluge komunikacije putem emaila uključujući slanje, primanje i upravljanje emailovima, kao i AI značajke, integraciju s kalendarom i videokonferenciju.',
  'terms.accounts.title': 'Korisnički računi',
  'terms.accounts.body': 'Ti si odgovoran za održavanje sigurnosti svojih vjerodajnica. Ne dijeli svoju lozinku niti dopuštaj neovlašteni pristup svom računu. Moraš imati najmanje 13 godina da koristiš ovu uslugu.',
  'terms.conduct.title': 'Prihvatljivo korištenje',
  'terms.conduct.body': 'Slažeš se da nećeš koristiti uslugu za slanje spama, malwarea, phishinga ili bilo kojeg ilegalnog sadržaja. Ne pokušavaj pristupiti računima drugih korisnika ili ometati infrastrukturu usluge.',
  'terms.content.title': 'Vlasništvo sadržaja',
  'terms.content.body': 'Zadržavaš vlasništvo nad svim sadržajem koji stvaraš i šalješ putem usluge. Ne tvrdimo vlasništvo nad tvojim emailovima ili privicima. Možemo obrađivati sadržaj prema potrebi za pružanje usluge.',
  'terms.limitation.title': 'Ograničenje odgovornosti',
  'terms.limitation.body': 'Chatyy se pruža "kako jest". Težimo 99,9% dostupnosti, ali ne jamčimo neprekidnu uslugu. Nismo odgovorni za neizravne, slučajne ili posljedične štete proizašle iz korištenja usluge.',
  'terms.termination.title': 'Zatvaranje računa',
  'terms.termination.body': 'Možemo obustaviti ili zatvoriti račune koji krše ove uvjete. Možeš izbrisati svoj račun u bilo kojem trenutku u Postavkama. Nakon zatvaranja, tvoji podaci će biti izbrisani u roku od 30 dana.',
  'terms.changes.title': 'Izmjene uvjeta',
  'terms.changes.body': 'Možemo povremeno ažurirati ove uvjete. Obavijestit ćemo o značajnim promjenama putem emaila ili obavijesti u aplikaciji. Nastavak korištenja nakon promjena predstavlja prihvaćanje ažuriranih uvjeta.',
