  'plans.faqWhatIsPlus': 'Što je Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'To je premium plan Chatyy koji štiti sve tvoje razgovore, fotografije i videe. S Chatyy One, čak i ako nešto slučajno obrišeš, možeš to povratiti u roku od 30 dana. Osim toga, dobiješ 200GB prostora za pohranu, One AI kao osobnog asistenta, i možeš slati datoteke do 100MB.',
  'plans.faqCancelAnswer': 'Tvoj plan ostaje aktivan do kraja plaćenog razdoblja. Nakon toga, vraćaš se na besplatni plan. Tvoje fotografije i videi koji premašuju 15GB bit će sačuvani još 30 dana za preuzimanje.',
  'plans.faqHowFamily': 'Kako funkcionira Pro plan?',
